1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
13	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
14	
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "formatDisplayName")
25	    @Mapping(target = "initials", source = "owner", qualifiedByName = "formatInitials")
26	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "formatMembershipNumber")
27	    @Mapping(target = "membershipTier", source = "owner", qualifiedByName = "formatMembershipTier")
28	    @Mapping(target = "locality", source = "owner", qualifiedByName = "formatLocality")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /** Fixed city-to-region table used to derive an owner's {@code locality}. */
32	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
33	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
34	
35	    /**
36	     * Derives an owner's {@code locality} from its city using the fixed city-to-region table
37	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), returning the canonical region string
38	     * or {@code 'UNKNOWN'} when the city is not in the table.
39	     */
40	    @Named("formatLocality")
41	    default String formatLocality(Owner owner) {
42	        if (owner == null) {
43	            return null;
44	        }
45	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
46	    }
47	
48	    /**
49	     * Determines an owner's membership tier for the read-only {@code membershipTier} field:
50	     * {@code 'SILVER'} when the owner had no namesakes at creation (namesakeCount is 0) and an
51	     * email address is present, otherwise {@code 'BRONZE'}.
52	     */
53	    @Named("formatMembershipTier")
54	    default OwnerDto.MembershipTierEnum formatMembershipTier(Owner owner) {
55	        if (owner == null) {
56	            return null;
57	        }
58	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
59	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
60	        return noNamesakes && hasEmail ? OwnerDto.MembershipTierEnum.SILVER : OwnerDto.MembershipTierEnum.BRONZE;
61	    }
