329	    private List<Owner> findHouseholdMembers(String lastName, String address) {
330	        String normalizedLastName = normalizeHouseholdField(lastName);
331	        String normalizedAddress = normalizeHouseholdAddress(address);
332	        if (normalizedLastName == null || normalizedAddress == null) {
333	            return List.of();
334	        }
335	        return ownerRepository.findAll().stream()
336	            .filter(existing -> normalizedLastName.equals(normalizeHouseholdField(existing.getLastName()))
