383	            .map(Owner::getHouseholdId)
384	            .filter(id -> id != null && !id.isBlank())
385	            .findFirst()
386	            .orElseGet(() -> generateHouseholdId(owner.getLastName(), owner.getAddress()));
387	        for (Owner member : members) {
388	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
389	                member.setHouseholdId(householdId);
